BEGIN READ ONLY;
SET LOCAL search_path=pg_catalog,public;
WITH expected AS(SELECT $scope_expected$null$scope_expected$::jsonb q),checks AS(SELECT jsonb_build_object(
 'binding_present',q IS NOT NULL AND q<>'null'::jsonb AND q->>'kind'='UC_SCOPE_QUALIFIED_ROLLBACK' AND q->>'source_sha256'='95ffe446fde157e7ed7d3341a6a14e529d785e5b50ac42719852895b3a706272',
 'exact_target_body',(SELECT md5(prosrc) FROM pg_proc WHERE oid='uc_document_chain_private.row_value(uuid,jsonb,uuid,uuid,boolean)'::regprocedure)='343a7508d39857f94665cb8cca1c8092',
 'old_metadata_and_authority_exact',(SELECT jsonb_build_object(
 'functions',(SELECT md5(coalesce(string_agg(md5((CASE WHEN p.oid='uc_document_chain_private.row_value(uuid,jsonb,uuid,uuid,boolean)'::regprocedure THEN to_jsonb(p)-'prosrc' ELSE to_jsonb(p) END)::text),'' ORDER BY p.oid),'')) FROM pg_proc p),
 'namespaces',(SELECT md5(coalesce(string_agg(md5(to_jsonb(n)::text),'' ORDER BY n.oid),'')) FROM pg_namespace n),
 'classes_security',(SELECT md5(coalesce(string_agg(md5(jsonb_build_array(c.oid,c.relname,c.relnamespace,c.relowner,c.relkind,c.relacl,c.relrowsecurity,c.relforcerowsecurity)::text),'' ORDER BY c.oid),'')) FROM pg_class c),
 'policies',(SELECT md5(coalesce(string_agg(md5(to_jsonb(p)::text),'' ORDER BY p.oid),'')) FROM pg_policy p),
 'default_acl',(SELECT md5(coalesce(string_agg(md5(to_jsonb(d)::text),'' ORDER BY d.oid),'')) FROM pg_default_acl d),
 'role_membership',(SELECT md5(coalesce(string_agg(md5(to_jsonb(a)::text),'' ORDER BY a.roleid,a.member,a.grantor),'')) FROM pg_auth_members a)
))=q->'catalog_before',
 'old_business_exact',(SELECT jsonb_agg(jsonb_build_object('table',s.t,'count',s.n,'hash',s.h) ORDER BY s.t) FROM (SELECT 'public.uc_automatic_admission_drafts' t,count(*) n,md5(coalesce(string_agg(md5(row_value),'' ORDER BY md5(row_value)),'')) h FROM (SELECT to_jsonb(r)::text AS row_value FROM public.uc_automatic_admission_drafts r WHERE r.organization_id=ANY(ARRAY['0e29e728-bcc5-46e6-a339-066fb1e9c726','04cc2cb4-c837-40ca-9767-6d6b95def7f5','f7701297-2c10-4f8e-8123-4016cee9984f','cdd87239-1b04-47c9-8cd6-7ad57af4c54b']::uuid[])) b
UNION ALL
SELECT 'public.uc_document_registry_records' t,count(*) n,md5(coalesce(string_agg(md5(row_value),'' ORDER BY md5(row_value)),'')) h FROM (SELECT to_jsonb(r)::text AS row_value FROM public.uc_document_registry_records r WHERE r.organization_id=ANY(ARRAY['0e29e728-bcc5-46e6-a339-066fb1e9c726','04cc2cb4-c837-40ca-9767-6d6b95def7f5','f7701297-2c10-4f8e-8123-4016cee9984f','cdd87239-1b04-47c9-8cd6-7ad57af4c54b']::uuid[])) b
UNION ALL
SELECT 'public.education_document_records' t,count(*) n,md5(coalesce(string_agg(md5(row_value),'' ORDER BY md5(row_value)),'')) h FROM (SELECT to_jsonb(r)::text AS row_value FROM public.education_document_records r WHERE r.organization_id=ANY(ARRAY['0e29e728-bcc5-46e6-a339-066fb1e9c726','04cc2cb4-c837-40ca-9767-6d6b95def7f5','f7701297-2c10-4f8e-8123-4016cee9984f','cdd87239-1b04-47c9-8cd6-7ad57af4c54b']::uuid[])) b
UNION ALL
SELECT 'public.org_documents' t,count(*) n,md5(coalesce(string_agg(md5(row_value),'' ORDER BY md5(row_value)),'')) h FROM (SELECT to_jsonb(r)::text AS row_value FROM public.org_documents r WHERE r.organization_id=ANY(ARRAY['0e29e728-bcc5-46e6-a339-066fb1e9c726','04cc2cb4-c837-40ca-9767-6d6b95def7f5','f7701297-2c10-4f8e-8123-4016cee9984f','cdd87239-1b04-47c9-8cd6-7ad57af4c54b']::uuid[])) b
UNION ALL
SELECT 'public.org_document_versions' t,count(*) n,md5(coalesce(string_agg(md5(row_value),'' ORDER BY md5(row_value)),'')) h FROM (SELECT to_jsonb(r)::text AS row_value FROM public.org_document_versions r WHERE r.organization_id=ANY(ARRAY['0e29e728-bcc5-46e6-a339-066fb1e9c726','04cc2cb4-c837-40ca-9767-6d6b95def7f5','f7701297-2c10-4f8e-8123-4016cee9984f','cdd87239-1b04-47c9-8cd6-7ad57af4c54b']::uuid[])) b
UNION ALL
SELECT 'uc_individual_orders_private.orders' t,count(*) n,md5(coalesce(string_agg(md5(row_value),'' ORDER BY md5(row_value)),'')) h FROM (SELECT to_jsonb(r)::text AS row_value FROM uc_individual_orders_private.orders r WHERE r.organization_id=ANY(ARRAY['0e29e728-bcc5-46e6-a339-066fb1e9c726','04cc2cb4-c837-40ca-9767-6d6b95def7f5','f7701297-2c10-4f8e-8123-4016cee9984f','cdd87239-1b04-47c9-8cd6-7ad57af4c54b']::uuid[])) b
UNION ALL
SELECT 'public.courses' t,count(*) n,md5(coalesce(string_agg(md5(row_value),'' ORDER BY md5(row_value)),'')) h FROM (SELECT to_jsonb(r)::text AS row_value FROM public.courses r WHERE r.organization_id=ANY(ARRAY['0e29e728-bcc5-46e6-a339-066fb1e9c726','04cc2cb4-c837-40ca-9767-6d6b95def7f5','f7701297-2c10-4f8e-8123-4016cee9984f','cdd87239-1b04-47c9-8cd6-7ad57af4c54b']::uuid[])) b
UNION ALL
SELECT 'public.enrollments' t,count(*) n,md5(coalesce(string_agg(md5(row_value),'' ORDER BY md5(row_value)),'')) h FROM (SELECT to_jsonb(r)::text AS row_value FROM public.enrollments r JOIN public.courses c ON c.id=r.course_id WHERE c.organization_id=ANY(ARRAY['0e29e728-bcc5-46e6-a339-066fb1e9c726','04cc2cb4-c837-40ca-9767-6d6b95def7f5','f7701297-2c10-4f8e-8123-4016cee9984f','cdd87239-1b04-47c9-8cd6-7ad57af4c54b']::uuid[])) b) s)=q->'business_before',
 'old_ledger_exact',(SELECT jsonb_build_object('count',count(*),'fingerprint',md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' ORDER BY version),''))) FROM supabase_migrations.schema_migrations t WHERE version<>'20261123190000')=q->'ledger_before',
 'one_exact_new_ledger',(SELECT count(*)=1 AND bool_and(name='uc_document_chain_draft_scope' AND cardinality(statements)=1 AND octet_length(convert_to(statements[1],'UTF8'))=5850 AND encode(sha256(convert_to(statements[1],'UTF8')),'hex')='95ffe446fde157e7ed7d3341a6a14e529d785e5b50ac42719852895b3a706272') FROM supabase_migrations.schema_migrations WHERE version='20261123190000')
 ) flags FROM expected) SELECT jsonb_build_object('observed_at',clock_timestamp(),'kind','UC_SCOPE_INDEPENDENT_READBACK','flags',flags,'accepted',(SELECT bool_and(coalesce(value='true'::jsonb,false)) FROM jsonb_each(flags)), 'source_sha256','95ffe446fde157e7ed7d3341a6a14e529d785e5b50ac42719852895b3a706272','current_ledger',(SELECT jsonb_build_object('count',count(*),'fingerprint',md5(coalesce(string_agg(md5(to_jsonb(t)::text),'' ORDER BY version),''))) FROM supabase_migrations.schema_migrations t),'business',(SELECT jsonb_agg(jsonb_build_object('table',s.t,'count',s.n,'hash',s.h) ORDER BY s.t) FROM (SELECT 'public.uc_automatic_admission_drafts' t,count(*) n,md5(coalesce(string_agg(md5(row_value),'' ORDER BY md5(row_value)),'')) h FROM (SELECT to_jsonb(r)::text AS row_value FROM public.uc_automatic_admission_drafts r WHERE r.organization_id=ANY(ARRAY['0e29e728-bcc5-46e6-a339-066fb1e9c726','04cc2cb4-c837-40ca-9767-6d6b95def7f5','f7701297-2c10-4f8e-8123-4016cee9984f','cdd87239-1b04-47c9-8cd6-7ad57af4c54b']::uuid[])) b
UNION ALL
SELECT 'public.uc_document_registry_records' t,count(*) n,md5(coalesce(string_agg(md5(row_value),'' ORDER BY md5(row_value)),'')) h FROM (SELECT to_jsonb(r)::text AS row_value FROM public.uc_document_registry_records r WHERE r.organization_id=ANY(ARRAY['0e29e728-bcc5-46e6-a339-066fb1e9c726','04cc2cb4-c837-40ca-9767-6d6b95def7f5','f7701297-2c10-4f8e-8123-4016cee9984f','cdd87239-1b04-47c9-8cd6-7ad57af4c54b']::uuid[])) b
UNION ALL
SELECT 'public.education_document_records' t,count(*) n,md5(coalesce(string_agg(md5(row_value),'' ORDER BY md5(row_value)),'')) h FROM (SELECT to_jsonb(r)::text AS row_value FROM public.education_document_records r WHERE r.organization_id=ANY(ARRAY['0e29e728-bcc5-46e6-a339-066fb1e9c726','04cc2cb4-c837-40ca-9767-6d6b95def7f5','f7701297-2c10-4f8e-8123-4016cee9984f','cdd87239-1b04-47c9-8cd6-7ad57af4c54b']::uuid[])) b
UNION ALL
SELECT 'public.org_documents' t,count(*) n,md5(coalesce(string_agg(md5(row_value),'' ORDER BY md5(row_value)),'')) h FROM (SELECT to_jsonb(r)::text AS row_value FROM public.org_documents r WHERE r.organization_id=ANY(ARRAY['0e29e728-bcc5-46e6-a339-066fb1e9c726','04cc2cb4-c837-40ca-9767-6d6b95def7f5','f7701297-2c10-4f8e-8123-4016cee9984f','cdd87239-1b04-47c9-8cd6-7ad57af4c54b']::uuid[])) b
UNION ALL
SELECT 'public.org_document_versions' t,count(*) n,md5(coalesce(string_agg(md5(row_value),'' ORDER BY md5(row_value)),'')) h FROM (SELECT to_jsonb(r)::text AS row_value FROM public.org_document_versions r WHERE r.organization_id=ANY(ARRAY['0e29e728-bcc5-46e6-a339-066fb1e9c726','04cc2cb4-c837-40ca-9767-6d6b95def7f5','f7701297-2c10-4f8e-8123-4016cee9984f','cdd87239-1b04-47c9-8cd6-7ad57af4c54b']::uuid[])) b
UNION ALL
SELECT 'uc_individual_orders_private.orders' t,count(*) n,md5(coalesce(string_agg(md5(row_value),'' ORDER BY md5(row_value)),'')) h FROM (SELECT to_jsonb(r)::text AS row_value FROM uc_individual_orders_private.orders r WHERE r.organization_id=ANY(ARRAY['0e29e728-bcc5-46e6-a339-066fb1e9c726','04cc2cb4-c837-40ca-9767-6d6b95def7f5','f7701297-2c10-4f8e-8123-4016cee9984f','cdd87239-1b04-47c9-8cd6-7ad57af4c54b']::uuid[])) b
UNION ALL
SELECT 'public.courses' t,count(*) n,md5(coalesce(string_agg(md5(row_value),'' ORDER BY md5(row_value)),'')) h FROM (SELECT to_jsonb(r)::text AS row_value FROM public.courses r WHERE r.organization_id=ANY(ARRAY['0e29e728-bcc5-46e6-a339-066fb1e9c726','04cc2cb4-c837-40ca-9767-6d6b95def7f5','f7701297-2c10-4f8e-8123-4016cee9984f','cdd87239-1b04-47c9-8cd6-7ad57af4c54b']::uuid[])) b
UNION ALL
SELECT 'public.enrollments' t,count(*) n,md5(coalesce(string_agg(md5(row_value),'' ORDER BY md5(row_value)),'')) h FROM (SELECT to_jsonb(r)::text AS row_value FROM public.enrollments r JOIN public.courses c ON c.id=r.course_id WHERE c.organization_id=ANY(ARRAY['0e29e728-bcc5-46e6-a339-066fb1e9c726','04cc2cb4-c837-40ca-9767-6d6b95def7f5','f7701297-2c10-4f8e-8123-4016cee9984f','cdd87239-1b04-47c9-8cd6-7ad57af4c54b']::uuid[])) b) s)) AS result FROM checks;
COMMIT;
